"""Refresh source-linked appendices without altering the authored workflow text."""
import json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DOCUMENT=ROOT/'DOCCRAFT_FULL_TECHNICAL_WORKFLOW.md'
MARKER='<!-- SOURCE_APPENDICES -->'
EXCLUDED={'node_modules','dist','generated','.venv','.venv-local','__pycache__','redis-bin','tests','__tests__','testing'}
def cell(value):return str(value).replace('|','\\|').replace('\n',' ')
def link(path,line=None):
    name=str(path.relative_to(ROOT));return f'[{name}{":"+str(line) if line else ""}]({name}{"#L"+str(line) if line else ""})'
def main():
    sections=['## Source-derived appendices','',
      'Generated by `scripts/build_technical_workflow_appendices.py` from the current source. These enumerate declarations and schemas, not independent completed features or successful integration tests. Regenerate after route/contract/navigation/schema changes.','',
      '### A. Every canonical document field','',
      '| Field | Type | Validation/configuration | Aliases |','| --- | --- | --- | --- |']
    contract=json.loads((ROOT/'shared/document-contract.json').read_text())
    for key,value in contract['fields'].items():
        configuration={k:v for k,v in value.items() if k not in ('type','aliases','label','question')}
        sections.append(f"| `{key}` | {cell(value.get('type','string'))} | {cell(json.dumps(configuration,ensure_ascii=False))} | {cell(', '.join(value.get('aliases',[])))} |")
    sections+=['','### B. Complete document requirement sets','']
    for key,value in contract['documents'].items():
        sections+=['#### '+key,'','- Required: '+', '.join('`'+v+'`' for v in value['required'])+'.','- Optional: '+', '.join('`'+v+'`' for v in value['optional'])+'.','- Conditional: `'+json.dumps(value.get('conditional',[]),ensure_ascii=False)+'`.','- Specific questions: `'+json.dumps(value.get('questions',{}),ensure_ascii=False)+'`.','']
    sections+=['### C. Bundled template declarations','',
      '| Template ID | Display name | Compatible document types | Additional requirements / conditional rules |','| --- | --- | --- | --- |']
    for key,value in json.loads((ROOT/'shared/template-schemas.json').read_text())['templates'].items():
        sections.append(f"| `{key}` | {cell(value.get('name',''))} | {cell(', '.join(value.get('documentTypes',[])))} | {cell(json.dumps(value.get('schema',{}),ensure_ascii=False))} |")
    sections+=['','### D. Complete Prisma model and enum declarations','',
      'These are physical model definitions, including compatibility fields and relations. A retained legacy field/table is not automatically an active business authority. Password/TOTP/key field names below are schema metadata; no credential values are included.','']
    for service in ('auth','chat','payment','quota'):
        path=ROOT/f'services/{service}/prisma/schema.prisma';source=path.read_text()
        declarations=re.findall(r'^(?:model|enum)\s+\w+\s*\{.*?^\}',source,re.M|re.S)
        sections+=['#### '+service,'',link(path),'','```prisma','\n\n'.join(declarations),'```','']
    sections+=['### E. Python/SQL-owned persistence entry points','',
      'The complete Admin DDL includes compatibility upgrades and both SQLite test/PostgreSQL forms; use the source links for exact column definitions and migration conditions. Document `_source` recovery/retention metadata is stored inside its slots JSON, not separate model columns.','',
      '| Owner / function | Exact source |','| --- | --- |',
      '| Document SQLAlchemy model | '+link(ROOT/'services/document/app/models/document.py')+' |',
      '| Custom document template model | '+link(ROOT/'services/document/app/models/custom_template.py')+' |',
      '| Document initialization/upgrades | '+link(ROOT/'services/document/app/services/db.py')+' |',
      '| Admin central schema/upgrades | '+link(ROOT/'services/admin-api/app/db/admin_db.py')+' |',
      '| Uploaded immutable template versions | '+link(ROOT/'services/admin-api/app/services/uploaded_templates.py')+' |',
      '| Entitlement overrides | '+link(ROOT/'services/admin-api/app/services/entitlements.py')+' |',
      '| GDPR soft-purge retry journal | '+link(ROOT/'services/admin-api/app/api/v1/gdpr.py')+' |',
      '| Durable billing automation receipt | '+link(ROOT/'services/admin-api/app/services/automation_inbox.py')+' |',
      '| Notification preferences/log/receipt schema | '+link(ROOT/'services/notification/src/services/db.service.ts')+' |','']
    sections+=['### F. Complete receiving-service permission declarations','',
      'A matching signature alone is insufficient: the receiving service also matches method/path/caller below and validates the request body/time/replay binding. Regexes are the literal receiving-service policy, not browser routes.','',
      '| Receiver | Method(s) | Path pattern | Authorized service callers |','| --- | --- | --- | --- |']
    permissions=json.loads((ROOT/'shared/service-permissions.json').read_text())
    for receiver,rules in permissions.items():
        for rule in rules:sections.append(f"| {receiver} | {cell(', '.join(rule['methods']))} | `{cell(rule['path'])}` | {cell(', '.join(rule['callers']))} |")
    sections+=['','### G. Declared HTTP route catalog','',
      'Literal route declarations from production source are listed with source locations. Prefixes, aliases and inherited middleware must be assembled using section 3 and each server/router mount. Wildcard/dynamically generated routes may represent several runtime URLs; the Chat complete/abandon loop and gateway proxies are explained in the main workflow. A declaration is not a live OpenAPI conformance claim.','']
    routes=[]
    pattern=re.compile(r"(?:@(?:router|app)\.|\b(?:router|app|fastify|server)\.)(get|post|put|patch|delete|options|head|all)\(\s*['\"]([^'\"]+)['\"]",re.I)
    for path in sorted((ROOT/'services').rglob('*')):
        if not path.is_file() or path.suffix not in ('.ts','.py','.mjs','.js') or any(part in EXCLUDED for part in path.relative_to(ROOT).parts) or '.test.' in path.name or path.name.startswith('test_'):continue
        source=path.read_text(errors='replace')
        for match in pattern.finditer(source):routes.append({'service':path.relative_to(ROOT).parts[1],'method':match[1].upper(),'path':match[2],'file':str(path.relative_to(ROOT)),'line':source[:match.start()].count('\n')+1})
    for service in sorted({r['service'] for r in routes}):
        sections+=['#### '+service,'','| Method | Declared path | Source |','| --- | --- | --- |']
        for row in (row for row in routes if row['service']==service):sections.append(f"| {row['method']} | `{cell(row['path'])}` | {link(ROOT/row['file'],row['line'])} |")
        sections+=['']
    sections+=['### H. All administrator navigation entries','',
      'Labels are reproduced literally, including historical naming such as Enterprise. Effective entitlement codes/limits remain the current Free/Pro/Max policy; a navigation label is not a fourth subscription contract.','',
      '| Section | Navigation ID | Display label |','| --- | --- | --- |']
    nav=ROOT/'admin/src/config/adminNavSections.tsx';source=nav.read_text();nav_rows=[];section=''
    for line in source.splitlines():
        heading=re.search(r"title:\s*'([^']+)'",line)
        if heading:section=heading[1]
        for match in re.finditer(r"label:\s*'([^']+)'\s*,\s*id:\s*'([^']+)'",line):
            nav_rows.append({'section':section,'id':match[2],'label':match[1]});sections.append(f'| {cell(section)} | `{match[2]}` | {cell(match[1])} |')
    sections+=['','### I. Current controlled MCP document tools','',
      '| Tool | Business purpose | Enforcement |','| --- | --- | --- |',
      '| `get_session_state` | Retrieve authorized committed draft state | Owned session context; no arbitrary account/session lookup. |',
      '| `update_slots` | Propose supported fields/item operations/clarifications | Literal evidence, supported schema, canonical validation, revision/lease and current ownership. |','',
      'Source: '+link(ROOT/'services/chat/src/services/mcp.service.ts')+'. These controlled document tools are distinct from any protected infrastructure/resource MCP endpoints.','',
      '### J. Reproduction and evidence index','',
      '- Full local checks: `scripts/phase4_regression.py`; actual results: `docs/system-audit/evidence/phase4/regression/summary.json`.','- Native isolated SQL/Redis/API recovery: `scripts/system_audit_phase4_stack.py`, `scripts/system_audit_phase4_probes.py`, `scripts/system_audit_phase4_payment.mts`.','- Real SQL notification receipt expiry/deduplication: `scripts/phase4_notification_receipt_probe.py`.','- Offline staging: `scripts/prepare_staging.py`, `scripts/verify_staging.py`; actual image/container/provider validation remains separately gated.','- Source change hashes: `docs/system-audit/evidence/phase4/change-manifest.json`.','- The workflow inventory JSON contains route/navigation declarations only; it includes no credentials or provider payloads.','']
    authored=DOCUMENT.read_text().split(MARKER)[0];DOCUMENT.write_text(authored+MARKER+'\n\n'+'\n'.join(sections))
    output=ROOT/'docs/system-audit/evidence/phase4/workflow-inventory.json';output.write_text(json.dumps({'scope':'Source declarations only, not live workflow verification','route_declarations':routes,'admin_navigation':nav_rows,'canonical_fields':list(contract['fields'])},indent=2)+'\n')
    print(json.dumps({'document':str(DOCUMENT.relative_to(ROOT)),'route_declarations':len(routes),'admin_navigation_entries':len(nav_rows),'canonical_fields':len(contract['fields'])}))
if __name__=='__main__':main()
